"""Capture numerical references, not bit-exact qualification of the Rust backend.

Requires numpy==1.26.4 and transformers==5.12.1. No model/network/GPU needed.
"""

import json
from pathlib import Path

import numpy as np
import transformers
from transformers.audio_utils import mel_filter_bank, spectrogram, window_function

assert np.__version__ == "1.26.4"
assert transformers.__version__ == "5.12.1"


def config(rate, fft, hop, mels, **overrides):
    return dict(
        sample_rate=rate, n_fft=fft, hop_length=hop, n_mels=mels,
        min_frequency=0.0, max_frequency=rate / 2, mel_scale="slaney",
        slaney_normalize=True, window="hann_periodic", center="reflect",
        fft_output="f32", drop_last_frame=True, log_floor=1e-10,
        dynamic_range=8.0, output_offset=4.0, output_scale=0.25,
    ) | overrides


cases = []
for name, n, valid, cfg in [
    ("slaney_16k_80", 2048, 1234, config(16000, 400, 160, 80)),
    ("slaney_24k_128", 5003, 4321, config(24000, 800, 240, 128)),
    ("htk_8k_uncentered", 777, 777, config(8000, 256, 64, 32,
        mel_scale="htk", center="none", window="hann_symmetric",
        slaney_normalize=False, drop_last_frame=False)),
    ("zero_22k_rectangular", 2049, 1601, config(22050, 512, 128, 48,
        center="zero", window="rectangular", dynamic_range=None,
        output_offset=0.0, output_scale=1.0, log_floor=1e-8)),
]:
    # Exactly representable synthetic PCM, identically generated by the Rust test.
    samples = (((np.arange(n, dtype=np.int64) * 7919 + 17) % 65536) - 32768).astype(np.float32) / 32768
    samples[valid:] = 0
    filters = mel_filter_bank(1 + cfg["n_fft"] // 2, cfg["n_mels"],
        cfg["min_frequency"], cfg["max_frequency"], cfg["sample_rate"],
        norm="slaney" if cfg["slaney_normalize"] else None,
        mel_scale=cfg["mel_scale"])
    window = window_function(cfg["n_fft"],
        "boxcar" if cfg["window"] == "rectangular" else "hann",
        periodic=cfg["window"] != "hann_symmetric")
    features = spectrogram(samples, window, frame_length=cfg["n_fft"],
        hop_length=cfg["hop_length"], power=2.0,
        center=cfg["center"] != "none",
        pad_mode="constant" if cfg["center"] == "zero" else "reflect",
        mel_filters=filters, mel_floor=cfg["log_floor"], log_mel="log10")
    if cfg["drop_last_frame"]:
        features = features[:, :-1]
    if cfg["dynamic_range"] is not None:
        features = np.maximum(features, features.max() - cfg["dynamic_range"])
    features = (features + cfg["output_offset"]) * cfg["output_scale"]
    frames = features.shape[1]
    cases.append(dict(name=name, config=cfg, samples=n, valid_samples=valid,
        shape=list(features.shape),
        frame_anchor_mask=[int(i * cfg["hop_length"] < valid) for i in range(frames)],
        features=features.flatten().tolist()))

output = dict(reference=dict(transformers=transformers.__version__, numpy=np.__version__,
    entry="transformers.audio_utils.spectrogram (NumPy CPU)",
    status="numerical reference only; not a bit-exact backend qualification"), cases=cases)
Path(__file__).with_name("log_mel.json").write_text(json.dumps(output, indent=2) + "\n")
